using LoyaltyService.Contracts;
using LoyaltyService.Domain;
namespace LoyaltyService.Application; public interface ILoyaltyRepository { Task<Loyalty> GetOrCreateAsync(string username, CancellationToken ct); Task<Loyalty> ChangeCountAsync(string username, int delta, CancellationToken ct); } public sealed class LoyaltyApplication(ILoyaltyRepository r) { private static LoyaltyDto Map(Loyalty x) => new(x.Status, x.Discount, x.ReservationCount); public async Task<LoyaltyDto> GetAsync(string u, CancellationToken ct) => Map(await r.GetOrCreateAsync(u, ct)); public async Task<LoyaltyDto> IncrementAsync(string u, CancellationToken ct) => Map(await r.ChangeCountAsync(u, 1, ct)); public async Task<LoyaltyDto> DecrementAsync(string u, CancellationToken ct) => Map(await r.ChangeCountAsync(u, -1, ct)); }
